@SpringBootTest(properties={"app.auth.jwt-secret=test-only-secret-that-is-at-least-32-bytes-long","app.maintenance.scan-cron=-","app.sla.scan-cron=-","app.inventory.warning-cron=-","app.storage.root=target/taskbook-test-uploads"})
@ActiveProfiles("local") @AutoConfigureMockMvc @Transactional
@EnabledIfSystemProperty(named="stage13.db-tests",matches="true")
class TaskbookAlignmentDatabaseIntegrationTest {
 @Autowired JdbcTemplate jdbc; @Autowired RepairRequestService repairs; @Autowired RepairAttachmentService reportFiles;
 @Autowired WorkOrderAttachmentService orderFiles; @Autowired WorkOrderService orders;
 @Autowired DispatchRecommendationService recommendations; @Autowired UserManagementService users;
 @Autowired com.cq.maintenance.maintenance.service.MaintenancePlanService plans;
 @Autowired com.cq.maintenance.maintenance.service.MaintenanceOrderGenerator generator;
 @Autowired com.cq.maintenance.inventory.service.InventoryService inventory;
 @Autowired com.cq.maintenance.security.AuthMapper accounts;
 @Autowired com.cq.maintenance.equipment.service.EquipmentTypeService equipmentTypes;
 @Autowired org.springframework.data.redis.core.StringRedisTemplate redis;
 @Autowired AuthService auth; @Autowired JwtService jwt; @Autowired TokenStore tokens; @Autowired MockMvc mvc;
 Long user(String name){return jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?",Long.class,name);}
 Long team(){return jdbc.queryForObject("SELECT id FROM org_team WHERE team_no='TEAM-01'",Long.class);}
 void login(String name,String role){var account=user(name);var workshop=jdbc.queryForObject("SELECT id FROM org_workshop WHERE workshop_no='WS-01'",Long.class);var principal=new LoginUser(account,name,name,"ENABLED",List.of(role),List.of(),List.of(team()),workshop,List.of());SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(principal,null,List.of()));}
 Long equipment(){String no="ALIGN-"+UUID.randomUUID();jdbc.update("INSERT INTO eqp_equipment(equipment_no,equipment_name,type_id,station_id,responsible_team_id,status,running_hours,qr_code) SELECT ?,?,t.id,s.id,?,'RUNNING',0,? FROM eqp_type t JOIN org_station s ON s.station_no='ST-01' WHERE t.type_code='CNC'",no,"约束对齐测试",team(),no);return jdbc.queryForObject("SELECT id FROM eqp_equipment WHERE equipment_no=?",Long.class,no);}
 com.cq.maintenance.repair.vo.RepairCreateVO submit(){login("reporter","REPORTER");return repairs.create(new RepairRequestCreateRequest(equipment(),RepairPriority.NORMAL,"异常振动",RepairSource.PC));}
 com.cq.maintenance.repair.vo.RepairCreateVO confirmed(){var pending=submit();login("supervisor","MAINTENANCE_SUPERVISOR");return repairs.confirm(pending.repairRequestId());}
 MockMultipartFile file(){return new MockMultipartFile("file","现场.txt","text/plain","现场故障记录".getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @AfterEach void clear()throws Exception{SecurityContextHolder.clearContext();Path root=Path.of("target/taskbook-test-uploads");if(Files.exists(root))try(var paths=Files.walk(root)){for(var p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
 @Test void pendingReportDoesNotCreateOrderOrChangeDevice(){var report=submit();assertNull(report.workOrderId());assertEquals("SUBMITTED",jdbc.queryForObject("SELECT status FROM mnt_repair_request WHERE id=?",String.class,report.repairRequestId()));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mnt_work_order WHERE repair_request_id=?",Integer.class,report.repairRequestId()));assertThrows(BusinessException.class,()->repairs.confirm(report.repairRequestId()));}
 @Test void confirmationIsUniqueAndTransfersOriginalEvidence()throws Exception{var report=submit();Long attachment=reportFiles.upload(report.repairRequestId(),file());assertNotNull(attachment);login("supervisor","MAINTENANCE_SUPERVISOR");var order=repairs.confirm(report.repairRequestId());assertThrows(BusinessException.class,()->repairs.confirm(report.repairRequestId()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM mnt_work_order WHERE repair_request_id=?",Integer.class,report.repairRequestId()));assertEquals(1,orderFiles.list(order.workOrderId()).size());assertArrayEquals(file().getBytes(),reportFiles.download(report.repairRequestId(),attachment).content());assertThrows(BusinessException.class,()->reportFiles.upload(report.repairRequestId(),file()));}
 @Test void pendingCancellationLeavesEquipmentRunning(){var report=submit();Long equipment=jdbc.queryForObject("SELECT equipment_id FROM mnt_repair_request WHERE id=?",Long.class,report.repairRequestId());repairs.cancel(report.repairRequestId(),new CancelWorkOrderRequest("误报",com.cq.maintenance.equipment.entity.EquipmentStatus.RUNNING));assertEquals("RUNNING",jdbc.queryForObject("SELECT status FROM eqp_equipment WHERE id=?",String.class,equipment));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mnt_work_order WHERE repair_request_id=?",Integer.class,report.repairRequestId()));}
 @Test void recommendedAssignmentRetainsSourceAndScoreSnapshot(){var order=confirmed();var candidate=recommendations.recommend(order.workOrderId()).get(0);orders.assign(order.workOrderId(),new DispatchRequest(candidate.engineerId(),candidate.teamId(),"采纳推荐",true));assertEquals("RECOMMENDED",jdbc.queryForObject("SELECT assignment_type FROM mnt_assignment_log WHERE work_order_id=?",String.class,order.workOrderId()));assertTrue(jdbc.queryForObject("SELECT score_snapshot FROM mnt_assignment_log WHERE work_order_id=?",String.class,order.workOrderId()).contains("totalScore"));}
 @Test void manualReassignmentBeforeAcceptanceRetainsOldEngineer(){var order=confirmed();var candidates=orders.engineers(order.workOrderId());assertTrue(candidates.size()>1);var first=candidates.get(0);var second=candidates.get(1);orders.assign(order.workOrderId(),new DispatchRequest(first.id(),first.teamId(),"首次派单"));orders.assign(order.workOrderId(),new DispatchRequest(second.id(),second.teamId(),"人员调整"));assertEquals(first.id(),jdbc.queryForObject("SELECT old_engineer_id FROM mnt_assignment_log WHERE work_order_id=? ORDER BY id DESC LIMIT 1",Long.class,order.workOrderId()));jdbc.update("UPDATE mnt_work_order SET accepted_at=NOW() WHERE id=?",order.workOrderId());assertThrows(BusinessException.class,()->orders.assign(order.workOrderId(),new DispatchRequest(first.id(),first.teamId(),"接单后改派")));}
 @Test void managerCannotUploadEngineerRepairEvidence(){var order=confirmed();jdbc.update("UPDATE mnt_work_order SET status='PROCESSING',assigned_engineer_id=? WHERE id=?",user("engineer"),order.workOrderId());assertThrows(BusinessException.class,()->orderFiles.upload(order.workOrderId(),"REPAIR",file()));login("engineer","ENGINEER");Long id=orderFiles.upload(order.workOrderId(),"REPAIR",file());assertNotNull(id);jdbc.update("UPDATE mnt_work_order SET status='COMPLETED',completed_at=NOW() WHERE id=?",order.workOrderId());assertThrows(BusinessException.class,()->orderFiles.upload(order.workOrderId(),"REPAIR",file()));}
 @Test void passwordResetRevokesBothOldTokenTypes()throws Exception{Long id=user("admin");long version=jdbc.queryForObject("SELECT password_version FROM sys_user WHERE id=?",Long.class,id);var access=jwt.issue(id,"admin",JwtService.ACCESS,version);var refresh=jwt.issue(id,"admin",JwtService.REFRESH,version);tokens.savePair(id,access,refresh);SecurityContextHolder.clearContext();mvc.perform(get("/api/auth/me").header("Authorization","Bearer "+access.value())).andExpect(status().isOk());login("admin","ADMIN");users.resetPassword(id,new PasswordResetRequest("ResetPass2026!"));SecurityContextHolder.clearContext();mvc.perform(get("/api/auth/me").header("Authorization","Bearer "+access.value())).andExpect(status().isUnauthorized());assertThrows(BusinessException.class,()->auth.refresh(refresh.value()));}
 @Test void simultaneousRefreshConsumptionHasOneWinner()throws Exception{Long id=user("admin");var access=jwt.issue(id,"admin",JwtService.ACCESS);var refresh=jwt.issue(id,"admin",JwtService.REFRESH);tokens.savePair(id,access,refresh);var claims=jwt.parse(refresh.value());var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{Callable<Boolean> action=()->{start.await();return tokens.consumeRefresh(claims,refresh.value());};var a=pool.submit(action);var b=pool.submit(action);start.countDown();assertEquals(1,(a.get()?1:0)+(b.get()?1:0));}finally{pool.shutdownNow();}}
 @Test void pmHistoryUsesFrozenPlanIdentityAndCannotMoveEquipment(){login("admin","ADMIN");Long equipment=equipment();String no="PM-ALIGN-"+System.nanoTime();Long id=plans.create(new com.cq.maintenance.maintenance.dto.MaintenancePlanRequest(no,"原计划名称",equipment,com.cq.maintenance.maintenance.entity.MaintenanceCycleType.WEEK,1,java.time.LocalDate.now(),null));jdbc.update("INSERT INTO pm_plan_item(plan_id,item_name,sort_no,required) VALUES(?,'检查项',1,1)",id);assertTrue(generator.generateIfDue(id,java.time.LocalDate.now()));plans.update(id,new com.cq.maintenance.maintenance.dto.MaintenancePlanRequest(no+"R","新计划名称",equipment,com.cq.maintenance.maintenance.entity.MaintenanceCycleType.WEEK,1,java.time.LocalDate.now().plusWeeks(1),null));assertEquals("原计划名称",plans.history(id).get(0).planName());assertEquals(no,plans.history(id).get(0).planNo());Long other=equipment();assertThrows(BusinessException.class,()->plans.update(id,new com.cq.maintenance.maintenance.dto.MaintenancePlanRequest(no,"不可换设备",other,com.cq.maintenance.maintenance.entity.MaintenanceCycleType.WEEK,1,java.time.LocalDate.now().plusWeeks(1),null)));}
 @Test void changedSafetyParametersRefreshAndCloseExistingWarning(){login("admin","ADMIN");Long warehouse=jdbc.queryForObject("SELECT id FROM inv_warehouse ORDER BY id LIMIT 1",Long.class);String no="WARN-ALIGN-"+System.nanoTime();jdbc.update("INSERT INTO inv_spare_part(spare_no,spare_name,unit,unit_price,lead_time_days,safety_days,status) VALUES(?,'测试备件','件',1,3,5,'ENABLED')",no);Long part=jdbc.queryForObject("SELECT id FROM inv_spare_part WHERE spare_no=?",Long.class,no);jdbc.update("INSERT INTO inv_stock(warehouse_id,spare_part_id,current_qty) VALUES(?,?,1)",warehouse,part);jdbc.update("INSERT INTO inv_transaction(transaction_no,warehouse_id,spare_part_id,transaction_type,qty_change,qty_before,qty_after,unit_price,operator_id) VALUES(?,?,?,'OUTBOUND',-30,31,1,1,?)",no,warehouse,part,user("admin"));inventory.refreshAllWarnings();assertEquals(new java.math.BigDecimal("5.00"),jdbc.queryForObject("SELECT threshold_qty FROM inv_warning WHERE warehouse_id=? AND spare_part_id=? AND status='OPEN'",java.math.BigDecimal.class,warehouse,part));inventory.updateSparePart(part,new com.cq.maintenance.inventory.dto.SparePartRequest(no,"测试备件",null,null,"件",java.math.BigDecimal.ONE,null,null,3,8,"ENABLED"));assertEquals(new java.math.BigDecimal("8.00"),jdbc.queryForObject("SELECT threshold_qty FROM inv_warning WHERE warehouse_id=? AND spare_part_id=? AND status='OPEN'",java.math.BigDecimal.class,warehouse,part));inventory.updateSparePart(part,new com.cq.maintenance.inventory.dto.SparePartRequest(no,"测试备件",null,null,"件",java.math.BigDecimal.ONE,null,null,3,0,"ENABLED"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM inv_warning WHERE warehouse_id=? AND spare_part_id=? AND status='OPEN'",Integer.class,warehouse,part));}
 @Test void deletedUserCannotBeReactivatedAndHistoricalIdentityRemains(){login("admin","ADMIN");Long id=user("warehouse");users.delete(id);assertEquals("DISABLED",jdbc.queryForObject("SELECT status FROM sys_user WHERE id=?",String.class,id));assertNotNull(jdbc.queryForObject("SELECT deleted_at FROM sys_user WHERE id=?",java.time.LocalDateTime.class,id));assertNull(accounts.findByUsername("warehouse"));assertTrue(accounts.findUsers().stream().noneMatch(u->id.equals(u.id())));assertThrows(BusinessException.class,()->users.detail(id));assertThrows(BusinessException.class,()->users.delete(user("admin")));}
 @Test @Transactional(propagation=org.springframework.transaction.annotation.Propagation.NOT_SUPPORTED) void equipmentTypeCacheCanSerializeAndReadBusinessValues(){var first=equipmentTypes.list();assertFalse(first.isEmpty());assertEquals(first,equipmentTypes.list());assertNotNull(redis.opsForValue().get("equipment-types::all"));}

}
